using SkiaSharp;

namespace WogSwitch;

internal static class JpegSmoke
{
    // Synthetic solid-color fixtures; no original game images or user data.
    internal static void Verify(Action<string> log)
    {
        foreach (var sample in new[] { ("baseline", ""), ("progressive", "") })
        {
            log("STEP native JPEG decode " + sample.Item1);
            using var bitmap = SKBitmap.Decode(Convert.FromBase64String(sample.Item2)) ?? throw new InvalidDataException("JPEG decode returned null");
            var color = bitmap.GetPixel(12, 8);
            if (bitmap.Width != 24 || bitmap.Height != 16 || color.Alpha != 255 ||
                Math.Abs(color.Red - 42) > 5 || Math.Abs(color.Green - 126) > 5 || Math.Abs(color.Blue - 210) > 5)
                throw new InvalidDataException("JPEG fixture pixel or dimension mismatch");
            log("PASS native JPEG decode " + sample.Item1 + ": 24x16, color and alpha verified");
        }
    }
}
